private static boolean running = true; // BEZ volatile
Thread worker = new Thread(() -> {
    long iteracje = 0;
    while (running) { iteracje++; } // JIT MOZE odczytac running RAZ i trzymac w rejestrze
    System.out.println("zauwazylem po " + iteracje);
});
worker.setDaemon(true); // bezpiecznik - JVM zakonczy proces mimo ewentualnej niekonczacej sie petli
worker.start();
Thread.sleep(200);
running = false; // moze NIGDY nie zostac zauwazone przez worker!
worker.join(2000);

private static volatile boolean running = true;
// Teraz GWARANCJA: zapis running=false w jednym watku bedzie natychmiast
// widoczny w drugim watku (bariera pamieci przy kazdym odczycie/zapisie pola volatile).

