static volatile boolean running = true;
Thread w = new Thread(() -> { long i=0; while(running) i++; System.out.println(i); });
w.start();
Thread.sleep(200);
running = false;
w.join(2000);
System.out.println(w.isAlive()); // false

static boolean running = true; // BEZ volatile
Thread w = new Thread(() -> { while(running) {} });
w.setDaemon(true);
w.start();
Thread.sleep(200);
running = false;
w.join(2000);
System.out.println("zauwazyl: " + !w.isAlive());

class NonVolatileHolder { boolean flag = true; }
class VolatileHolder { volatile boolean flag = true; }
// dla obu: watek daemon while(holder.flag){}, main ustawia flag=false po 100ms, porownaj isAlive() po join(1000)

volatile boolean paused = false, stopped = false;
Thread w = new Thread(() -> {
    while (!stopped) { if (!paused) { /* praca */ } try { Thread.sleep(5); } catch (Exception e) {} }
});
w.start();
Thread.sleep(100); paused = true;
Thread.sleep(100); stopped = true;
w.join(2000);

volatile int counter = 0;
// 4 watki x 100_000 wywolan counter++
System.out.println("oczekiwany=400000 rzeczywisty=" + counter); // czesto < 400000 mimo volatile

volatile boolean signal = false;
Thread w = new Thread(() -> {
    for (int i = 0; i < 20 && !signal; i++) { try { Thread.sleep(50); } catch (Exception e) {} }
    System.out.println(signal ? "zauwazono" : "nie zauwazono w limicie");
});
w.start();
Thread.sleep(300); signal = true;
w.join(3000);

volatile boolean stop = false;
Thread w = new Thread(() -> { while(!stop) {} });
w.setDaemon(true); w.start();
w.join(500);
System.out.println(w.isAlive()); // true
stop = true;
w.join(2000);
System.out.println(w.isAlive()); // false

Thread w = new Thread(() -> { long i=0; while(!stop) i++; });
w.setDaemon(true); // JVM zakonczy sie mimo watku, gdyby ten nigdy nie zobaczyl zmiany
w.start();
Thread.sleep(300);
stop = true;

volatile boolean paused = false, stop = false;
Thread w = new Thread(() -> {
    long licznik = 0;
    while (!stop) { if (paused) { try { Thread.sleep(10); } catch (Exception e) {} } else licznik++; }
    System.out.println(licznik);
});
w.start();
Thread.sleep(200); paused = true;
Thread.sleep(200); paused = false;
Thread.sleep(200); stop = true;
w.join(3000);

// volatile: watek na pewno zakonczy petle po widocznym ustawieniu flagi
// bez volatile: watek MOZE dzialac w nieskonczonosc (musi byc daemon jako bezpiecznik)
// porownaj liczby iteracji i to, czy join(2000) zwrocil PRZED czy PO timeout

volatile boolean running = true;
Thread w1 = new Thread(() -> { long i=0; while(running) i++; System.out.println("w1: "+i); });
Thread w2 = new Thread(() -> { long i=0; while(running) i++; System.out.println("w2: "+i); });
w1.start(); w2.start();
Thread.sleep(200); running = false;
w1.join(2000); w2.join(2000);

volatile int progress = 0;
Thread producent = new Thread(() -> { for (int i=0;i<100;i++) { progress = i+1; try { Thread.sleep(10); } catch (Exception e) {} } });
Thread monitor = new Thread(() -> { while (progress < 100) { System.out.println(progress); try { Thread.sleep(30); } catch (Exception e) {} } });
producent.start(); monitor.start();
producent.join(5000); monitor.join(5000);

record Config(int limit) {}
volatile Config current = new Config(10);
Thread w = new Thread(() -> { long suma=0; for (int i=0;i<500;i++) suma += current.limit(); System.out.println(suma); });
w.start();
Thread.sleep(100); current = new Config(20);
w.join(2000);

volatile long total = 0;
// 4 watki x 50_000 wywolan total += 3
long oczekiwany = 4*50_000*3;
System.out.println("oczekiwany="+oczekiwany+" rzeczywisty="+total); // volatile NIE chroni +=

volatile boolean dataReady = false;
volatile String data = null;
Thread producent = new Thread(() -> { try { Thread.sleep(150); } catch (Exception e) {} data = "wynik"; dataReady = true; });
Thread konsument = new Thread(() -> {
    for (int i=0;i<200 && !dataReady;i++) { try { Thread.sleep(10); } catch (Exception e) {} }
    System.out.println(data);
});
producent.start(); konsument.start();
producent.join(3000); konsument.join(3000);

volatile boolean stop = false;
Thread[] w = new Thread[3];
long[] iteracje = new long[3];
for (int i=0;i<3;i++) { final int idx=i; w[i] = new Thread(() -> { while(!stop) iteracje[idx]++; }); }
for (Thread t : w) t.start();
Thread.sleep(300); stop = true;
for (Thread t : w) t.join(2000);
System.out.println(Arrays.toString(iteracje));

volatile int[] snapshot = {1,2,3};
Thread czytelnik = new Thread(() -> {
    for (int i=0;i<20;i++) { System.out.println(Arrays.stream(snapshot).sum()); try { Thread.sleep(20); } catch (Exception e) {} }
});
czytelnik.start();
Thread.sleep(100); snapshot = new int[]{10,20,30,40};
czytelnik.join(2000);

volatile boolean flag = false;
long[] czasZauwazenia = new long[1];
Thread w = new Thread(() -> { while(!flag) {} czasZauwazenia[0] = System.nanoTime(); });
w.start();
long czasUstawienia = System.nanoTime();
flag = true;
w.join(2000);
System.out.println((czasZauwazenia[0]-czasUstawienia)/1_000_000.0 + "ms");

volatile boolean stop = false;
Thread w1 = new Thread(() -> { while(!stop) {} });
Thread w2 = new Thread(() -> { while(!stop) {} });
w1.start(); w2.start();
Thread.sleep(250); stop = true;
w1.join(2000); w2.join(2000);
System.out.println(!w1.isAlive() + " " + !w2.isAlive());

record Settings(int threshold, String mode) {}
volatile Settings settings = new Settings(5, "NORMAL");
// 2 watki czytajace co 20ms, max 15 razy, wypisujace settings
Thread.sleep(150); settings = new Settings(10, "FAST");

volatile String latestMessage = null;
// producent: 5x (Thread.sleep(100); latestMessage = "msg"+i;)
// subskrybenci: petla odczytujaca latestMessage co 15ms, licznik++ gdy != poprzednio widziana wartosc

volatile boolean stopRequested = false;
Thread[] w = new Thread[5]; long[] iteracje = new long[5];
// uruchom 5 watkow, main po 300ms ustawia stopRequested=true, join(2000) kazdy, raportuj isAlive() i iteracje[idx]

volatile long lastHeartbeat = System.currentTimeMillis();
Thread w = new Thread(() -> { for (int i=0;i<50;i++) { lastHeartbeat = System.currentTimeMillis(); try { Thread.sleep(20); } catch (Exception e) {} } });
w.start();
for (int i=0;i<10;i++) { Thread.sleep(100); System.out.println(System.currentTimeMillis()-lastHeartbeat > 200 ? "STALE" : "ALIVE"); }
w.join(3000);

volatile boolean paused = false, stop = false;
long[] kroki = {0};
Thread w = new Thread(() -> { while (!stop && kroki[0] < 1000) { if (paused) { try { Thread.sleep(5); } catch (Exception e) {} } else kroki[0]++; } });
w.start();
// main: naprzemiennie paused=true/false co 100ms kilka razy, na koncu stop=true
w.join(5000);
System.out.println(kroki[0]);

int zauwazone = 0;
for (int proba = 0; proba < 5; proba++) {
    boolean[] running = {true}; // NIE volatile, ale opakowane w tablice zeby lambda mogla je czytac
    Thread w = new Thread(() -> { while(running[0]) {} });
    w.setDaemon(true); w.start();
    Thread.sleep(200); running[0] = false;
    w.join(2000);
    if (!w.isAlive()) zauwazone++;
}
System.out.println(zauwazone + "/5");

volatile List<String> items = List.of();
Thread producent = new Thread(() -> {
    for (int i=0;i<3;i++) {
        try { Thread.sleep(100); } catch (Exception e) {}
        List<String> nowa = new ArrayList<>(items); nowa.add("item"+i);
        items = List.copyOf(nowa);
    }
});
// czytelnicy: for (i<20) { System.out.println(items.size()); Thread.sleep(30); }
// bezpieczne, bo items jest ZAWSZE kompletna, niemutowalna lista (nigdy 'w trakcie' modyfikacji)

volatile boolean stop = false;
long LIMIT = 5_000_000;
long[] iteracje = {0};
Thread w = new Thread(() -> { while (!stop && iteracje[0] < LIMIT) iteracje[0]++; });
w.start();
Thread.sleep(200); stop = true;
w.join(2000);
System.out.println("iteracje="+iteracje[0]+" zakonczyl przez: "+(iteracje[0]>=LIMIT ? "limit" : "flage stop"));

// (a) bez volatile: watek daemon, MOZE nigdy nie zauwazyc zmiany (bezpiecznik: daemon)
// (b) z volatile: watek MA GWARANCJE zauwazenia zmiany w rozsadnym czasie
// (c) z volatile + limit: dodatkowe zabezpieczenie na wypadek nieprzewidzianych sytuacji
// dla kazdego: uruchom, main ustawia flage po 200ms, join(2000), wypisz isAlive() i iteracje
